void can_v_id_class_delete (void)
{
  Can_V_Rx curr ;

  for (curr = can_v_vars.init.can_v_rx_list ; curr ; curr = curr->obj.init.next)
    {
      can_v_id_set_delete (curr->obj.init.id_set) ;
    }
}

